DROP TABLE IF EXISTS `candidate_certificate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `candidate_certificate` (
  `certificate_uuid` char(60) COLLATE utf8_unicode_ci NOT NULL,
  `certificate_type` tinyint(1) DEFAULT '0',
  `candidate_id` int(11) NOT NULL,
  `candidate_work_history_id` int(11) DEFAULT NULL,
  `exam_uuid` char(60) COLLATE utf8_unicode_ci DEFAULT NULL,
  `store_id` int(11) DEFAULT NULL,
  `company_id` int(11) DEFAULT NULL,
  `parent_company_id` int(11) DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `staff_id` int(11) DEFAULT NULL,
  `is_deleted` tinyint(1) DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`certificate_uuid`),
  KEY `idx-candidate_certificate-staff_id` (`staff_id`),
  KEY `idx-candidate_certificate-candidate_id` (`candidate_id`),
  KEY `idx-candidate_certificate-candidate_work_history_id` (`candidate_work_history_id`),
  KEY `idx-candidate_certificate-exam_uuid` (`exam_uuid`),
  KEY `idx-candidate_certificate-store_id` (`store_id`),
  KEY `idx-candidate_certificate-company_id` (`company_id`),
  KEY `idx-candidate_certificate-parent_company_id` (`parent_company_id`),
  CONSTRAINT `fk-candidate_certificate-candidate_id` FOREIGN KEY (`candidate_id`) REFERENCES `candidate` (`candidate_id`),
  CONSTRAINT `fk-candidate_certificate-candidate_work_history_id` FOREIGN KEY (`candidate_work_history_id`) REFERENCES `candidate_work_history` (`id`),
  CONSTRAINT `fk-candidate_certificate-company_id` FOREIGN KEY (`company_id`) REFERENCES `company` (`company_id`),
  CONSTRAINT `fk-candidate_certificate-exam_uuid` FOREIGN KEY (`exam_uuid`) REFERENCES `exam` (`exam_uuid`),
  CONSTRAINT `fk-candidate_certificate-parent_company_id` FOREIGN KEY (`parent_company_id`) REFERENCES `company` (`company_id`),
  CONSTRAINT `fk-candidate_certificate-staff_id` FOREIGN KEY (`staff_id`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk-candidate_certificate-store_id` FOREIGN KEY (`store_id`) REFERENCES `store` (`store_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
