--
-- Table structure for table `company`
--

DROP TABLE IF EXISTS `company`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `company` (
  `company_id` int(11) NOT NULL AUTO_INCREMENT,
  `parent_company_id` int(11) DEFAULT NULL,
  `staff_id` int(11) DEFAULT NULL COMMENT 'managed by',
  `company_name` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `company_common_name_en` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `company_common_name_ar` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `company_description_en` text COLLATE utf8_unicode_ci,
  `company_description_ar` text COLLATE utf8_unicode_ci,
  `company_website` text COLLATE utf8_unicode_ci,
  `company_email` varchar(225) COLLATE utf8_unicode_ci DEFAULT NULL,
  `company_logo` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `commercial_licence` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `company_hourly_rate` decimal(10,3) DEFAULT NULL,
  `company_bonus_commission` decimal(6,3) DEFAULT NULL COMMENT '% of bonus as profit',
  `company_followup` tinyint(1) DEFAULT '1',
  `total_candidate` bigint(20) DEFAULT '0',
  `no_of_active_requests` int(11) DEFAULT '0',
  `is_request_updates_in_30_days` tinyint(1) DEFAULT '0',
  `company_followup_interval_weeks` smallint(6) DEFAULT '1',
  `company_last_followup_datetime` datetime DEFAULT CURRENT_TIMESTAMP,
  `company_next_followup_datetime` datetime DEFAULT CURRENT_TIMESTAMP,
  `company_approved_to_hire` tinyint(1) DEFAULT '1',
  `company_status_override` tinyint(1) DEFAULT '0',
  `company_created_at` datetime NOT NULL,
  `company_updated_at` datetime NOT NULL,
  `last_request_datetime` datetime DEFAULT NULL,
  `last_payment_datetime` datetime DEFAULT NULL,
  `deleted` smallint(1) NOT NULL DEFAULT '0',
  `country_id` int(11) DEFAULT NULL,
  `currency_code` char(3) COLLATE utf8_unicode_ci DEFAULT 'KWD',
  PRIMARY KEY (`company_id`),
  KEY `idx-company-parent_company_id` (`parent_company_id`),
  KEY `idx-company-staff_id` (`staff_id`),
  KEY `ind-company-country_id` (`country_id`),
  KEY `ind-company-currency_code` (`currency_code`),
  CONSTRAINT `fk-company-country_id` FOREIGN KEY (`country_id`) REFERENCES `country` (`country_id`),
  CONSTRAINT `fk-company-parent_company_id` FOREIGN KEY (`parent_company_id`) REFERENCES `company` (`company_id`) ON DELETE CASCADE,
  CONSTRAINT `fk-company-staff_id` FOREIGN KEY (`staff_id`) REFERENCES `staff` (`staff_id`) ON DELETE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

