DROP TABLE IF EXISTS `company_request`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `company_request` (
  `company_request_uuid` char(60) COLLATE utf8_unicode_ci NOT NULL,
  `utm_uuid` char(64) COLLATE utf8_unicode_ci DEFAULT NULL,
  `contact_uuid` char(60) COLLATE utf8_unicode_ci DEFAULT NULL,
  `company_name` varchar(100) COLLATE utf8_unicode_ci NOT NULL,
  `company_email` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `contact_position` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `contact_name` varchar(100) COLLATE utf8_unicode_ci NOT NULL,
  `contact_receive_email` tinyint(1) DEFAULT '1',
  `phone_number` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `requesting_for` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `contact_password_hash` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `status` tinyint(1) DEFAULT '0' COMMENT 'pending=0, processing=1,  accepted=2, rejected=3',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `currency_code` char(3) COLLATE utf8_unicode_ci DEFAULT 'KWD',
  `country_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`company_request_uuid`),
  KEY `idx-company_request-contact_uuid` (`contact_uuid`),
  KEY `ind-company_request-country_id` (`country_id`),
  KEY `ind-company_request-currency_code` (`currency_code`),
  KEY `ind-company_request-utm_uuid` (`utm_uuid`),
  CONSTRAINT `fk-company_request-contact_uuid` FOREIGN KEY (`contact_uuid`) REFERENCES `contact` (`contact_uuid`) ON DELETE SET NULL,
  CONSTRAINT `fk-company_request-country_id` FOREIGN KEY (`country_id`) REFERENCES `country` (`country_id`),
  CONSTRAINT `fk-company_request-utm_uuid` FOREIGN KEY (`utm_uuid`) REFERENCES `campaign` (`utm_uuid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
