--
-- Table structure for table `contact`
--

DROP TABLE IF EXISTS `contact`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `contact` (
  `contact_uuid` char(60) COLLATE utf8_unicode_ci NOT NULL,
  `utm_uuid` char(64) COLLATE utf8_unicode_ci DEFAULT NULL,
  `contact_name` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `contact_email` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `contact_new_email` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `contact_email_verification` tinyint(1) DEFAULT '0',
  `contact_email_verified_by` int(11) DEFAULT NULL,
  `contact_limit_email` datetime DEFAULT NULL,
  `contact_password_hash` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `contact_receive_email` tinyint(1) DEFAULT '1',
  `contact_auth_key` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL,
  `contact_password_reset_token` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `contact_receive_notification` tinyint(1) DEFAULT '1',
  `contact_receive_suggestions` tinyint(1) DEFAULT '1',
  `contact_status` tinyint(1) DEFAULT '10',
  `contact_created_at` datetime NOT NULL,
  `contact_updated_at` datetime NOT NULL,
  `ip_address` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `deleted` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`contact_uuid`),
  UNIQUE KEY `contact_email` (`contact_email`),
  UNIQUE KEY `contact_password_reset_token` (`contact_password_reset_token`),
  KEY `ind-contact-contact_email_verified_by` (`contact_email_verified_by`),
  KEY `ind-contact-utm_uuid` (`utm_uuid`),
  CONSTRAINT `fk-contact-contact_email_verified_by` FOREIGN KEY (`contact_email_verified_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk-contact-utm_uuid` FOREIGN KEY (`utm_uuid`) REFERENCES `campaign` (`utm_uuid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

