--
-- Table structure for table `daily_standup_answer`
--

DROP TABLE IF EXISTS `daily_standup_answer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `daily_standup_answer` (
  `answer_uuid` char(60) COLLATE utf8_unicode_ci NOT NULL,
  `staff_id` int(11) DEFAULT NULL,
  `question_uuid` char(60) COLLATE utf8_unicode_ci DEFAULT NULL,
  `question` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `answer` text COLLATE utf8_unicode_ci,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`answer_uuid`),
  KEY `idx-daily_standup_answer-staff_id` (`staff_id`),
  KEY `idx-daily_standup_answer-question_uuid` (`question_uuid`),
  CONSTRAINT `fk-daily_standup_answer-question_uuid` FOREIGN KEY (`question_uuid`) REFERENCES `daily_standup_question` (`question_uuid`),
  CONSTRAINT `fk-daily_standup_answer-staff_id` FOREIGN KEY (`staff_id`) REFERENCES `staff` (`staff_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

