DROP TABLE IF EXISTS `suggestion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `suggestion` (
  `suggestion_uuid` char(60) COLLATE utf8_unicode_ci NOT NULL,
  `request_uuid` char(60) COLLATE utf8_unicode_ci NOT NULL,
  `fulltimer_uuid` char(60) COLLATE utf8_unicode_ci DEFAULT NULL,
  `candidate_id` int(11) DEFAULT NULL,
  `note_uuid` char(60) COLLATE utf8_unicode_ci NOT NULL,
  `story_uuid` char(60) COLLATE utf8_unicode_ci DEFAULT NULL,
  `suggestion_status` tinyint(2) DEFAULT '0' COMMENT '1-Suggested , 2- rejected, 3- accepted',
  `mail_to_company` tinyint(1) DEFAULT '0',
  `suggestion_datetime` datetime NOT NULL,
  PRIMARY KEY (`suggestion_uuid`),
  KEY `idx-suggestion-request_uuid` (`request_uuid`),
  KEY `idx-suggestion-fulltimer_uuid` (`fulltimer_uuid`),
  KEY `idx-suggestion-candidate_id` (`candidate_id`),
  KEY `idx-suggestion-note_uuid` (`note_uuid`),
  KEY `idx-suggestion-story_uuid` (`story_uuid`),
  CONSTRAINT `fk-suggestion-candidate_id` FOREIGN KEY (`candidate_id`) REFERENCES `candidate` (`candidate_id`),
  CONSTRAINT `fk-suggestion-fulltimer_uuid` FOREIGN KEY (`fulltimer_uuid`) REFERENCES `fulltimer` (`fulltimer_uuid`),
  CONSTRAINT `fk-suggestion-note_uuid` FOREIGN KEY (`note_uuid`) REFERENCES `note` (`note_uuid`),
  CONSTRAINT `fk-suggestion-request_uuid` FOREIGN KEY (`request_uuid`) REFERENCES `request` (`request_uuid`),
  CONSTRAINT `fk-suggestion-story_uuid` FOREIGN KEY (`story_uuid`) REFERENCES `story` (`story_uuid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

