  `candidate_id` int(11) DEFAULT NULL,
  `prev_candidate_id` int(11) DEFAULT NULL,
  `store_id` int(11) DEFAULT NULL,
  `store_name` varchar(225) COLLATE utf8_unicode_ci DEFAULT NULL,
  `company_id` int(11) DEFAULT NULL,
  `company_name` varchar(225) COLLATE utf8_unicode_ci DEFAULT NULL,
  `company_email` varchar(225) COLLATE utf8_unicode_ci DEFAULT NULL,
