  `transfer_confirmation_id` varchar(128) COLLATE utf8_unicode_ci DEFAULT NULL,
  `transfer_file_id` int(11) DEFAULT NULL,
  `transfer_benef_name` char(60) COLLATE utf8_unicode_ci DEFAULT NULL,
  `transfer_benef_iban` char(50) COLLATE utf8_unicode_ci DEFAULT NULL,
