  `company_hourly_rate` decimal(10,3) DEFAULT NULL,
  `hours` double unsigned DEFAULT '0',
  `minutes` tinyint(2) DEFAULT '0',
  `seconds` tinyint(2) DEFAULT '0',
  `bonus` decimal(10,3) DEFAULT NULL,
  `bonus_commission` decimal(10,3) DEFAULT NULL COMMENT 'bonus as profit in KWD',
  `transfer_cost` decimal(10,3) DEFAULT NULL,
  `candidate_total` decimal(10,3) DEFAULT NULL,
  `company_total` decimal(10,3) DEFAULT NULL,
  `deleted` smallint(1) NOT NULL DEFAULT '0',
  `paid` smallint(1) NOT NULL DEFAULT '0',
  `tc_created_at` datetime NOT NULL,
  `tc_updated_at` datetime NOT NULL,
  `currency_code` char(3) COLLATE utf8_unicode_ci DEFAULT 'KWD',
  PRIMARY KEY (`tc_id`),
  UNIQUE KEY `idx-transfer_candidate-transfer_confirmation_id` (`transfer_confirmation_id`,`bank_id`,`deleted`),
  KEY `idx-tc-transfer_id` (`transfer_id`),
  KEY `idx-tc-candidate_id` (`candidate_id`),
  KEY `idx-transfer_candidate-store_id` (`store_id`),
  KEY `idx-transfer_candidate-company_id` (`company_id`),
  KEY `idx-transfer_candidate-bank_id` (`bank_id`),
  KEY `idx-transfer_candidate-transfer_file_id` (`transfer_file_id`),
  CONSTRAINT `fk-tc-candidate_id` FOREIGN KEY (`candidate_id`) REFERENCES `candidate` (`candidate_id`) ON DELETE CASCADE,
  CONSTRAINT `fk-tc-transfer_id` FOREIGN KEY (`transfer_id`) REFERENCES `transfer` (`transfer_id`) ON DELETE CASCADE,
  CONSTRAINT `fk-transfer_candidate-CASCADE` FOREIGN KEY (`transfer_file_id`) REFERENCES `transfer_file` (`transfer_file_id`) ON DELETE CASCADE,
  CONSTRAINT `fk-transfer_candidate-bank_id` FOREIGN KEY (`bank_id`) REFERENCES `bank` (`bank_id`),
  CONSTRAINT `fk-transfer_candidate-company_id` FOREIGN KEY (`company_id`) REFERENCES `company` (`company_id`) ON DELETE SET NULL,
  CONSTRAINT `fk-transfer_candidate-store_id` FOREIGN KEY (`store_id`) REFERENCES `store` (`store_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=338 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
